package com.example.jalalidaily;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
public class MainActivity extends Activity{
 LinearLayout root,days,items;TextView monthTitle;int year,month,day;final int blue=Color.rgb(23,59,114);
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(blue);int[] j=Jalali.fromGregorian(LocalDate.now());year=j[0];month=j[1];day=j[2];if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},4);draw();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(blue);t.setGravity(Gravity.CENTER);t.setPadding(9,12,9,12);return t;}
 void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,18,16,12);root.setBackgroundColor(Color.WHITE);setContentView(root);root.addView(text("تقویم و یادداشت شمسی",23));LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);root.addView(nav);Button prev=new Button(this);prev.setText("ماه قبل");nav.addView(prev);monthTitle=text("",19);nav.addView(monthTitle,new LinearLayout.LayoutParams(0,-2,1));Button next=new Button(this);next.setText("ماه بعد");nav.addView(next);prev.setOnClickListener(v->move(-1));next.setOnClickListener(v->move(1));days=new LinearLayout(this);days.setOrientation(1);root.addView(days);ScrollView sc=new ScrollView(this);items=new LinearLayout(this);items.setOrientation(1);sc.addView(items);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button add=new Button(this);add.setText("+ یادداشت جدید");root.addView(add);add.setOnClickListener(v->editor());renderCalendar();renderNotes();}
 void move(int delta){month+=delta;if(month>12){month=1;year++;}if(month<1){month=12;year--;}day=Math.min(day,Jalali.daysInMonth(year,month));renderCalendar();renderNotes();}
 void renderCalendar(){days.removeAllViews();monthTitle.setText(Jalali.MONTHS[month-1]+" "+year);String[] names={"ش","ی","د","س","چ","پ","ج"};LinearLayout hdr=new LinearLayout(this);for(String n:names){TextView t=text(n,14);hdr.addView(t,new LinearLayout.LayoutParams(0,-2,1));}days.addView(hdr);LocalDate first=Jalali.toGregorian(year,month,1);int offset=(first.getDayOfWeek().getValue()+1)%7;int count=Jalali.daysInMonth(year,month);for(int r=0;r<6;r++){LinearLayout line=new LinearLayout(this);for(int col=0;col<7;col++){int d=r*7+col-offset+1;TextView cell=text(d>=1&&d<=count?String.valueOf(d):"",15);if(d==day)cell.setBackgroundColor(0xFFE3EEFF);if(d>=1&&d<=count)cell.setOnClickListener(v->{day=d;renderCalendar();renderNotes();});line.addView(cell,new LinearLayout.LayoutParams(0,(int)(48*getResources().getDisplayMetrics().density),1));}days.addView(line);if((r+1)*7-offset>=count)break;}}
 void renderNotes(){items.removeAllViews();String key=Jalali.key(new int[]{year,month,day});items.addView(text("یادداشت‌های "+Jalali.label(new int[]{year,month,day}),18));ArrayList<JSONObject> list=Store.forDay(this,key);if(list.isEmpty())items.addView(text("برای این روز یادداشتی وجود ندارد",14));for(JSONObject o:list){LinearLayout line=new LinearLayout(this);line.setOrientation(1);line.setPadding(12,8,12,8);line.setBackgroundColor(0xFFF2F6FD);line.addView(text(o.optString("time")+"  "+o.optString("title"),17));line.addView(text(o.optString("body"),14));Button del=new Button(this);del.setText("حذف");line.addView(del);del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("این یادداشت حذف شود؟").setNegativeButton("انصراف",null).setPositiveButton("حذف",(x,w)->{Store.delete(this,o.optLong("id"));renderNotes();Widgets.refresh(this);}).show());items.addView(line);}}
 void editor(){LinearLayout form=new LinearLayout(this);form.setPadding(25,10,25,0);form.setOrientation(1);EditText title=new EditText(this);title.setHint("عنوان یادداشت");form.addView(title);EditText body=new EditText(this);body.setHint("توضیحات");form.addView(body);form.addView(text("ساعت یادآوری (اختیاری)",15));TimePicker picker=new TimePicker(this);picker.setIs24HourView(true);form.addView(picker);CheckBox remind=new CheckBox(this);remind.setText("ارسال اعلان در این ساعت");form.addView(remind);ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle(Jalali.label(new int[]{year,month,day})).setView(scroll).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(dialog,which)->{String t=title.getText().toString().trim();if(t.isEmpty()){Toast.makeText(this,"عنوان خالی است",Toast.LENGTH_SHORT).show();return;}int h=picker.getHour(),m=picker.getMinute();String time=String.format(Locale.US,"%02d:%02d",h,m);LocalDate date=Jalali.toGregorian(year,month,day);long at=date.atTime(h,m).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();long id=Store.add(this,Jalali.key(new int[]{year,month,day}),t,body.getText().toString(),time,at);if(remind.isChecked()&&at>System.currentTimeMillis())schedule(id,t,body.getText().toString(),at);renderNotes();Widgets.refresh(this);}).show();}
 void schedule(long id,String title,String body,long at){Intent i=new Intent(this,ReminderReceiver.class);i.putExtra("title",title);i.putExtra("body",body);i.putExtra("id",(int)(id&0x7fffffff));PendingIntent pi=PendingIntent.getBroadcast(this,(int)(id&0x7fffffff),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}
 @Override protected void onResume(){super.onResume();Widgets.refresh(this);}
}